-- Preset decks live in the DB with fixed UUIDs so players.active_deck_id can reference them.
-- RLS for decks/deck_cards is defined in 20260522000000_fix_auth_trigger_and_rls.sql.
INSERT INTO decks (id, user_id, name, cover_emoji, is_preset, created_at) VALUES
  ('00000000-0000-4000-8000-000000000001', NULL, 'Ataque Frontal',     '⚔️', true, '2026-01-01T00:00:01Z'),
  ('00000000-0000-4000-8000-000000000002', NULL, 'Defensa Total',      '🛡️', true, '2026-01-01T00:00:02Z'),
  ('00000000-0000-4000-8000-000000000003', NULL, 'Equilibrio',         '⚖️', true, '2026-01-01T00:00:03Z'),
  ('00000000-0000-4000-8000-000000000004', NULL, 'Prueba Consumibles', '🧪', true, '2026-01-01T00:00:04Z')
ON CONFLICT (id) DO UPDATE
  SET name = EXCLUDED.name, cover_emoji = EXCLUDED.cover_emoji, is_preset = true, user_id = NULL;

-- Drop legacy presets with random ids (players.active_deck_id falls back to NULL via FK).
DELETE FROM decks WHERE is_preset AND id NOT IN (
  '00000000-0000-4000-8000-000000000001',
  '00000000-0000-4000-8000-000000000002',
  '00000000-0000-4000-8000-000000000003',
  '00000000-0000-4000-8000-000000000004'
);

DELETE FROM deck_cards WHERE deck_id IN (
  '00000000-0000-4000-8000-000000000001',
  '00000000-0000-4000-8000-000000000002',
  '00000000-0000-4000-8000-000000000003',
  '00000000-0000-4000-8000-000000000004'
);

